CREATE TABLE integration_connectors (
 id uuid PRIMARY KEY, "organizationId" uuid NOT NULL REFERENCES organizations(id), "creatorId" uuid NOT NULL REFERENCES accounts(id), "actorId" uuid NOT NULL REFERENCES accounts(id), "branchId" uuid NOT NULL REFERENCES branches(id), "sourceId" uuid NOT NULL REFERENCES crm_sources(id), label varchar(160) NOT NULL CHECK(length(trim(label))>0), "encryptedSecret" text NOT NULL, state varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(state IN ('ACTIVE','DISABLED')), version integer NOT NULL DEFAULT 1 CHECK(version>0), "createdAt" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,"organizationId")
);
CREATE INDEX integration_connectors_scope ON integration_connectors("organizationId",state);
CREATE TABLE integration_connector_versions (
 id uuid PRIMARY KEY, "organizationId" uuid NOT NULL REFERENCES organizations(id), "connectorId" uuid NOT NULL, version integer NOT NULL CHECK(version>0), "actorId" uuid NOT NULL REFERENCES accounts(id), reason varchar(1000) NOT NULL CHECK(length(trim(reason))>=3), data jsonb NOT NULL, "eventId" uuid NOT NULL UNIQUE REFERENCES domain_events(id), "createdAt" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("connectorId",version), FOREIGN KEY("connectorId","organizationId") REFERENCES integration_connectors(id,"organizationId")
);
CREATE TABLE integration_deliveries (
 id uuid PRIMARY KEY, "organizationId" uuid NOT NULL REFERENCES organizations(id), "connectorId" uuid NOT NULL, "externalId" varchar(120) NOT NULL CHECK("externalId" ~ '^[A-Za-z0-9_-]{1,120}$'), "payloadHash" char(64) NOT NULL, status varchar(20) NOT NULL CHECK(status IN ('DELIVERED','FAILED')), "leadId" uuid REFERENCES leads(id), "failureCode" varchar(40), "eventId" uuid NOT NULL UNIQUE REFERENCES domain_events(id), "occurredAt" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("connectorId","externalId"), FOREIGN KEY("connectorId","organizationId") REFERENCES integration_connectors(id,"organizationId"), CHECK((status='DELIVERED' AND "leadId" IS NOT NULL AND "failureCode" IS NULL) OR (status='FAILED' AND "leadId" IS NULL AND "failureCode" IS NOT NULL))
);
CREATE TRIGGER s25_connector_versions_immutable BEFORE UPDATE OR DELETE ON integration_connector_versions FOR EACH ROW EXECUTE FUNCTION s25_immutable();
CREATE TRIGGER s25_connectors_no_delete BEFORE DELETE ON integration_connectors FOR EACH ROW EXECUTE FUNCTION s25_immutable();
CREATE TRIGGER s25_deliveries_no_delete BEFORE DELETE ON integration_deliveries FOR EACH ROW EXECUTE FUNCTION s25_immutable();
CREATE FUNCTION s25_connector_scope() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM branches WHERE id=NEW."branchId" AND "organizationId"=NEW."organizationId") OR NOT EXISTS(SELECT 1 FROM crm_sources WHERE id=NEW."sourceId" AND "organizationId"=NEW."organizationId" AND name='Website' AND "builtIn") THEN RAISE EXCEPTION 'S25 connector scope mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM accounts a LEFT JOIN employees e ON e."accountId"=a.id WHERE a.id=NEW."actorId" AND (a.kind='OWNER' OR a.kind='STAFF' AND e."organizationId"=NEW."organizationId")) THEN RAISE EXCEPTION 'S25 internal connector actor required'; END IF;
 IF TG_OP='UPDATE' AND ((NEW.id,NEW."organizationId",NEW."creatorId",NEW."actorId",NEW."branchId",NEW."sourceId",NEW.label,NEW."createdAt") IS DISTINCT FROM (OLD.id,OLD."organizationId",OLD."creatorId",OLD."actorId",OLD."branchId",OLD."sourceId",OLD.label,OLD."createdAt") OR NEW.version<>OLD.version+1 OR OLD.state='DISABLED') THEN RAISE EXCEPTION 'S25 connector identity/transition mismatch'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER s25_connector_scope BEFORE INSERT OR UPDATE ON integration_connectors FOR EACH ROW EXECUTE FUNCTION s25_connector_scope();
CREATE FUNCTION s25_connector_evidence() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE h integration_connector_versions; e domain_events; a audit_events; BEGIN
 SELECT * INTO h FROM integration_connector_versions WHERE "connectorId"=NEW.id AND version=NEW.version; SELECT * INTO e FROM domain_events WHERE id=h."eventId"; SELECT * INTO a FROM audit_events WHERE id=(e.payload->>'auditEventId')::uuid;
 IF h.id IS NULL OR e."eventName" IS DISTINCT FROM 'integration.connector_changed' OR e."subjectId" IS DISTINCT FROM NEW.id::text OR e."subjectType" IS DISTINCT FROM 'integration_connector' OR e."organizationId" IS DISTINCT FROM NEW."organizationId" OR e."actorId" IS DISTINCT FROM h."actorId" OR a."subjectId" IS DISTINCT FROM NEW.id::text OR a."subjectType" IS DISTINCT FROM 'integration_connector' OR a."actorId" IS DISTINCT FROM h."actorId" OR a.reason IS DISTINCT FROM h.reason OR a.after IS DISTINCT FROM h.data OR h.data->>'id' IS DISTINCT FROM NEW.id::text OR h.data->>'branchId' IS DISTINCT FROM NEW."branchId"::text OR h.data->>'sourceId' IS DISTINCT FROM NEW."sourceId"::text OR h.data->>'actorId' IS DISTINCT FROM NEW."actorId"::text OR h.data->>'label' IS DISTINCT FROM NEW.label OR h.data->>'state' IS DISTINCT FROM NEW.state OR (h.data->>'version')::integer IS DISTINCT FROM NEW.version THEN RAISE EXCEPTION 'S25 connector evidence mismatch'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER s25_connector_evidence AFTER INSERT OR UPDATE ON integration_connectors DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION s25_connector_evidence();
CREATE FUNCTION s25_delivery_scope() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='UPDATE' AND ((NEW.id,NEW."organizationId",NEW."connectorId",NEW."externalId",NEW."payloadHash") IS DISTINCT FROM (OLD.id,OLD."organizationId",OLD."connectorId",OLD."externalId",OLD."payloadHash") OR OLD.status='DELIVERED') THEN RAISE EXCEPTION 'S25 delivery identity is immutable'; END IF;
 IF NEW."leadId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM leads l JOIN integration_connectors c ON c.id=NEW."connectorId" WHERE l.id=NEW."leadId" AND l."organizationId"=NEW."organizationId" AND l."branchId"=c."branchId" AND l."sourceId"=c."sourceId") THEN RAISE EXCEPTION 'S25 delivery lead scope mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER s25_delivery_scope BEFORE INSERT OR UPDATE ON integration_deliveries FOR EACH ROW EXECUTE FUNCTION s25_delivery_scope();
CREATE FUNCTION s25_delivery_evidence() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE e domain_events; a audit_events; BEGIN
 SELECT * INTO e FROM domain_events WHERE id=NEW."eventId"; SELECT * INTO a FROM audit_events WHERE id=(e.payload->>'auditEventId')::uuid;
 IF e."eventName" IS DISTINCT FROM 'integration.delivery_changed' OR e."subjectId" IS DISTINCT FROM NEW.id::text OR e."subjectType" IS DISTINCT FROM 'integration_delivery' OR e."organizationId" IS DISTINCT FROM NEW."organizationId" OR a."subjectId" IS DISTINCT FROM NEW.id::text OR a."subjectType" IS DISTINCT FROM 'integration_delivery' OR a."actorId" IS DISTINCT FROM e."actorId" OR a.after->>'connectorId' IS DISTINCT FROM NEW."connectorId"::text OR a.after->>'externalId' IS DISTINCT FROM NEW."externalId" OR a.after->>'leadId' IS DISTINCT FROM NEW."leadId"::text OR a.after->>'failureCode' IS DISTINCT FROM NEW."failureCode" OR a.after->>'status' IS DISTINCT FROM NEW.status OR a.after->>'payloadHash' IS DISTINCT FROM NEW."payloadHash" THEN RAISE EXCEPTION 'S25 delivery evidence mismatch'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER s25_delivery_evidence AFTER INSERT OR UPDATE ON integration_deliveries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION s25_delivery_evidence();
DO $$ DECLARE prior_expression text; BEGIN
 SELECT pg_get_expr(conbin,conrelid) INTO prior_expression FROM pg_constraint WHERE conrelid='domain_events'::regclass AND conname='domain_events_eventName_catalogue_check';
 IF prior_expression IS NULL THEN RAISE EXCEPTION 'Existing catalogue required'; END IF;
 ALTER TABLE domain_events DROP CONSTRAINT "domain_events_eventName_catalogue_check";
 EXECUTE format('ALTER TABLE domain_events ADD CONSTRAINT "domain_events_eventName_catalogue_check" CHECK ((%s) OR "eventName" IN (''integration.connector_changed'',''integration.delivery_changed''))',prior_expression);
END $$;
